create table if not exists public.daily_checklist (user_id uuid not null references auth.users(id) on delete cascade,date date not null,checks jsonb not null default '[false,false,false,false,false,false,false,false,false,false,false,false,false]'::jsonb,updated_at timestamptz not null default now(),primary key(user_id,date)); alter table public.daily_checklist enable row level security; drop policy if exists "own_select" on public.daily_checklist; create policy "own_select" on public.daily_checklist for select using(auth.uid()=user_id); drop policy if exists "own_insert" on public.daily_checklist; create policy "own_insert" on public.daily_checklist for insert with check(auth.uid()=user_id); drop policy if exists "own_update" on public.daily_checklist; create policy "own_update" on public.daily_checklist for update using(auth.uid()=user_id) with check(auth.uid()=user_id);